import re


def sv(svg, w, h):
    """Scale an SVG to given dimensions."""
    svg = re.sub(r'width="[^"]*"', f'width="{w}"', svg, count=1)
    svg = re.sub(r'height="[^"]*"', f'height="{h}"', svg, count=1)
    return svg


