HP = {k: v for k, v in PLANTS.items() if v["category"] == "houseplant"}
GD = {k: v for k, v in PLANTS.items() if v["category"] == "garden"}
AL = {k: v for k, v in PLANTS.items() if v["category"] == "allotment"}


def plant(name, w=200, h=224):
    """Return the SVG for a plant, scaled to the given dimensions."""
    if name not in PLANTS:
        raise ValueError(f"Plant not found: {name}")
    return sv(PLANTS[name]["svg"], w, h)


ALL_NAMES = list(PLANTS.keys())
HOUSEPLANT_NAMES = list(HP.keys())
GARDEN_NAMES = list(GD.keys())
ALLOTMENT_NAMES = list(AL.keys())
